INSERT INTO branch (id, label, description) VALUES ('foundations', 'Math and ML foundations', 'The quantitative ground: linear algebra, probability, optimization, and how learning systems generalize.');
INSERT INTO branch (id, label, description) VALUES ('models', 'Model literacy', 'How frontier models behave: tokens, context limits, sampling, failure modes, and model selection.');
INSERT INTO branch (id, label, description) VALUES ('context', 'Prompt and context engineering', 'Shaping what a model sees: instructions, examples, structured output, and context budgets.');
INSERT INTO branch (id, label, description) VALUES ('retrieval', 'Retrieval and memory', 'Getting the right knowledge into context: search, embeddings, RAG, and durable memory.');
INSERT INTO branch (id, label, description) VALUES ('tools', 'Tools and integration', 'Letting models act: function calling, MCP servers, APIs, browsers, and sandboxes.');
INSERT INTO branch (id, label, description) VALUES ('agents', 'Agent architecture', 'Loops, planning, multi-agent topologies, state, handoff, and long-running work.');
INSERT INTO branch (id, label, description) VALUES ('evals', 'Evals and reliability', 'Proving behavior: test sets, graders, regression gates, and production monitoring.');
INSERT INTO branch (id, label, description) VALUES ('safety', 'Safety, security and governance', 'Bounding authority: prompt injection, permissions, policy, risk tiers, and audit.');
INSERT INTO branch (id, label, description) VALUES ('infra', 'Infrastructure and operations', 'Serving, routing, cost, latency, observability, and incident response for AI systems.');
INSERT INTO branch (id, label, description) VALUES ('data', 'Data and training', 'Datasets, labeling, fine-tuning, distillation, and preference optimization.');
INSERT INTO branch (id, label, description) VALUES ('multimodal', 'Multimodal and creative generation', 'Image, video, audio, and voice generation with consistency, rights, and taste.');
INSERT INTO branch (id, label, description) VALUES ('product', 'Product and strategy', 'Choosing what to build, pricing AI work, change management, and portfolio decisions.');
INSERT INTO branch (id, label, description) VALUES ('judgment', 'Judgment and collaboration', 'Calibration, verification, scoping, and working well across human and agent teams.');
INSERT INTO level (level, label, human, agent) VALUES (0, 'None', 'No exposure.', 'Capability absent.');
INSERT INTO level (level, label, human, agent) VALUES (1, 'Aware', 'Can explain it and recognize it in use.', 'Has instructions; succeeds on simple cases.');
INSERT INTO level (level, label, human, agent) VALUES (2, 'Assisted', 'Does it with guidance or templates.', 'Succeeds with a tool or skill file; needs review.');
INSERT INTO level (level, label, human, agent) VALUES (3, 'Independent', 'Does it unaided on real work.', 'Passes its eval set; safe to run with spot checks.');
INSERT INTO level (level, label, human, agent) VALUES (4, 'Lead', 'Teaches it and sets the team''s standard.', 'Passes adversarial evals; trusted inside its gates.');
INSERT INTO level (level, label, human, agent) VALUES (5, 'Frontier', 'Extends the state of the art.', 'Measurably best-in-class on public or held-out benchmarks.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('linear-algebra', 'foundations', 1, 'Linear algebra for ML', 'Vectors, matrices, projections, and decompositions as used in embeddings and attention.', 'Derive attention scores by hand for a toy example.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('probability', 'foundations', 1, 'Probability and statistics', 'Distributions, expectation, sampling error, and confidence intervals.', 'Compute a confidence interval for an eval pass rate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('optimization', 'foundations', 2, 'Optimization and gradient descent', 'Loss surfaces, gradient methods, learning rates, and regularization.', 'Train a small model and explain each hyperparameter''s effect.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('neural-nets', 'foundations', 2, 'Neural network fundamentals', 'Layers, backpropagation, and why depth helps.', 'Implement and train a feedforward network on a real dataset.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('transformers', 'foundations', 3, 'Transformer internals', 'Attention, positional encoding, KV cache, and scaling behavior.', 'Implement a minimal transformer and profile its KV cache.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('interpretability', 'foundations', 5, 'Interpretability methods', 'Probing, attribution, and feature analysis of model internals.', 'Publish an analysis that locates a behavior in model activations.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('token-economics', 'models', 1, 'Tokens and context limits', 'Tokenization, context windows, and how length drives cost and quality.', 'Estimate cost and context fit for a real workload within 10%.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('sampling', 'models', 1, 'Sampling and determinism', 'Temperature, top-p, seeds, and when outputs should vary.', 'Show a task where sampling settings change the pass rate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('failure-modes', 'models', 2, 'Model failure modes', 'Hallucination, sycophancy, refusal, truncation, and instruction drift.', 'Reproduce three failure modes and a mitigation for each.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('model-selection', 'models', 2, 'Model selection and routing', 'Matching task difficulty to model tier on quality, latency, and cost.', 'Route a workload across tiers and report the quality/cost trade.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('reasoning-modes', 'models', 3, 'Reasoning and extended thinking', 'When to spend thinking budget, and how to read and bound it.', 'Measure accuracy gain per thinking-token budget on a task.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('model-frontier', 'models', 4, 'Frontier tracking', 'Reading model cards, benchmarks, and releases without hype.', 'Write a dated capability memo with sources for a new model.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('instruction-writing', 'context', 1, 'Instruction writing', 'Clear, scoped, testable instructions with explicit done conditions.', 'Rewrite a vague prompt so a grader can check every requirement.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('few-shot', 'context', 2, 'Examples and few-shot design', 'Choosing examples that teach the boundary, not just the center.', 'Show pass-rate change from example selection on a held-out set.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('structured-output', 'context', 2, 'Structured output', 'Schemas, JSON modes, and validation-retry loops.', 'Ship a schema-validated extractor with a measured failure rate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('context-budget', 'context', 3, 'Context budgeting', 'Deciding what enters context, in what order, and what gets compacted.', 'Cut context size 50% with no eval regression.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('prompt-caching', 'context', 3, 'Prompt caching', 'Ordering stable prefixes to cut latency and cost.', 'Report cache hit rate and cost change on a real workload.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('skill-authoring', 'context', 3, 'Skill and instruction-pack authoring', 'Packaging reusable know-how as skills with triggers and done conditions.', 'Publish a skill that activates on its triggers and passes its own eval.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('search-basics', 'retrieval', 1, 'Search and keyword retrieval', 'BM25, filters, and when lexical search beats embeddings.', 'Build a lexical baseline and report recall@k.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('embeddings', 'retrieval', 2, 'Embeddings and vector search', 'Embedding models, similarity, indexes, and their failure cases.', 'Compare two embedding models on a labeled query set.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('rag', 'retrieval', 3, 'Retrieval-augmented generation', 'Chunking, hybrid retrieval, reranking, and grounded citation.', 'Ship a RAG system with measured groundedness and citation accuracy.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('agent-memory', 'retrieval', 3, 'Agent memory design', 'Episodic, semantic, and procedural memory with write and decay rules.', 'Show a memory policy that improves task success across sessions.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('knowledge-graphs', 'retrieval', 4, 'Knowledge graphs', 'Entity and relation modeling for multi-hop retrieval.', 'Answer multi-hop questions a flat index fails on.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('function-calling', 'tools', 2, 'Function calling', 'Tool schemas, argument validation, and error returns a model can act on.', 'Expose three tools and measure correct-call rate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('mcp', 'tools', 2, 'Model Context Protocol', 'Building and consuming MCP servers: tools, resources, prompts, auth.', 'Ship an MCP server used by two different clients.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('api-integration', 'tools', 2, 'API and SaaS integration', 'Wrapping external APIs with auth, pagination, rate limits, and retries.', 'Integrate an API with idempotent writes and backoff.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('code-execution', 'tools', 3, 'Sandboxed code execution', 'Running generated code in isolated environments with resource limits.', 'Run untrusted code in a sandbox with enforced limits.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('computer-use', 'tools', 4, 'Browser and computer use', 'Operating GUIs and browsers through screenshots and actions.', 'Complete a multi-page web task with a verified end state.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('agent-loop', 'agents', 2, 'Agent loop design', 'Observe-think-act loops, stop conditions, and step budgets.', 'Build a loop that halts correctly on success, failure, and budget.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('planning', 'agents', 3, 'Planning and decomposition', 'Breaking goals into checkable steps and replanning on new evidence.', 'Show a plan that adapts after an injected failure.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('multi-agent', 'agents', 4, 'Multi-agent orchestration', 'Topologies, delegation briefs, result synthesis, and conflict handling.', 'Run a fan-out workflow that beats a single agent on a measured task.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('state-handoff', 'agents', 3, 'State and handoff', 'Checkpoints, resumable work, and handoff notes another agent can act on.', 'Resume a task in a fresh session from a handoff file alone.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('long-horizon', 'agents', 5, 'Long-horizon autonomy', 'Multi-hour work with self-checks, budgets, and recovery.', 'Complete a multi-hour task with a full receipt trail.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('agent-sdk', 'agents', 3, 'Agent SDKs and frameworks', 'Building on agent SDKs and graph frameworks without lock-in.', 'Port one agent between two frameworks behind one interface.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('test-sets', 'evals', 2, 'Eval set construction', 'Representative, labeled cases including adversarial and edge cases.', 'Build a versioned eval set with a documented sampling method.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('llm-judges', 'evals', 3, 'Model-graded evaluation', 'Rubrics, judge calibration against humans, and judge bias.', 'Report judge-human agreement on a labeled subset.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('regression-gates', 'evals', 3, 'Regression gates in CI', 'Evals that can fail a build, with locked fixtures and thresholds.', 'Show a CI run that fails on a seeded regression.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('agent-evals', 'evals', 4, 'Agent and trajectory evals', 'Scoring tool use, trajectories, and end states, not just final text.', 'Evaluate an agent on end-state checks across 50+ tasks.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('production-monitoring', 'evals', 4, 'Production monitoring', 'Tracing, drift detection, online evals, and feedback loops.', 'Detect and attribute a real quality drop from traces.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('prompt-injection', 'safety', 2, 'Prompt injection defense', 'Treating fetched content as data and separating instructions from inputs.', 'Pass an injection suite against a tool-using agent.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('permissions', 'safety', 3, 'Least-privilege tool authority', 'Scoped credentials, human gates for irreversible actions, revocation.', 'Show an action the model cannot talk past a gate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('data-privacy', 'safety', 2, 'Data privacy and PII', 'Redaction, retention, residency, and consent in AI pipelines.', 'Run a pipeline with verified PII redaction before external calls.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('red-teaming', 'safety', 4, 'Red teaming', 'Adversarial probing for jailbreaks, misuse, and unsafe actions.', 'Publish a red-team report with reproducible findings.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('ai-governance', 'safety', 4, 'AI governance and risk tiering', 'Use-case triage, risk tiers, policy, and regulatory mapping.', 'Ship a risk-tiered AI policy adopted by a team.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('audit-trails', 'safety', 3, 'Audit trails and attestation', 'Append-only logs and signed receipts for agent actions.', 'Reconstruct an agent''s actions from its audit log alone.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('serving', 'infra', 2, 'Model serving and APIs', 'Hosted APIs, gateways, rate limits, streaming, and fallbacks.', 'Serve a feature with streaming and a provider fallback.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('cost-engineering', 'infra', 3, 'Cost engineering', 'Budgets, per-task unit cost, caching, and batch processing.', 'Cut unit cost 30% with no eval regression.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('observability', 'infra', 3, 'LLM observability', 'Traces, spans, token accounting, and latency breakdowns.', 'Trace a multi-step agent run end to end.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('self-hosting', 'infra', 4, 'Self-hosted inference', 'GPU sizing, quantization, batching, and open-weight deployment.', 'Serve an open-weight model at a target latency and cost.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('incident-response', 'infra', 4, 'AI incident response', 'Runbooks, rollback, and postmortems for model and agent failures.', 'Run a postmortem with root cause and a regression test.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('data-curation', 'data', 2, 'Dataset curation', 'Sourcing, cleaning, deduplication, and licensing of training data.', 'Publish a dataset card with provenance and licenses.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('labeling', 'data', 2, 'Labeling and annotation', 'Guidelines, inter-rater agreement, and model-assisted labeling.', 'Report inter-rater agreement on a labeled batch.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('synthetic-data', 'data', 3, 'Synthetic data generation', 'Generating, filtering, and validating model-made training data.', 'Show a synthetic set that improves a held-out metric.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('fine-tuning', 'data', 4, 'Fine-tuning and adapters', 'Supervised fine-tuning, LoRA, and when not to fine-tune.', 'Fine-tune a model that beats prompting on a measured task.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('preference-optimization', 'data', 5, 'Preference optimization', 'RLHF, DPO, and reward modeling.', 'Train with preference data and report win rate.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('image-generation', 'multimodal', 1, 'Image generation', 'Prompting image models for composition, style, and text rendering.', 'Produce an on-brief image set that passes a review rubric.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('video-generation', 'multimodal', 3, 'Video generation', 'Text- and image-to-video, shot planning, and motion control.', 'Deliver a multi-shot sequence with consistent subjects.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('voice-audio', 'multimodal', 2, 'Voice and audio generation', 'Speech synthesis, voice design, and music generation.', 'Ship a narrated asset with a consistent designed voice.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('character-consistency', 'multimodal', 4, 'Character and brand consistency', 'Keeping identity, palette, and style stable across an asset set.', 'Produce a 10-asset set with one character and brand system.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('media-rights', 'multimodal', 3, 'Media rights and provenance', 'Licensing, likeness, provider output terms, and provenance records.', 'Attach a provenance record to every published asset.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('creative-direction', 'multimodal', 4, 'Creative direction', 'Taste, briefs, and editorial judgment over generated media.', 'Direct a campaign whose assets pass an independent review.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('use-case-discovery', 'product', 1, 'AI use-case discovery', 'Finding workflows where AI changes cost, speed, or quality.', 'Rank ten use cases by value and feasibility with evidence.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('ai-ux', 'product', 2, 'AI interaction design', 'Designing for uncertainty, streaming, review, and recovery.', 'Ship a flow where users correct AI output in one step.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('ai-economics', 'product', 3, 'AI unit economics and pricing', 'Pricing outcomes, margins under inference cost, and usage risk.', 'Model margin per customer under three usage scenarios.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('change-management', 'product', 3, 'AI adoption and change management', 'Training, workflow redesign, and measuring adoption.', 'Run a rollout with a measured adoption curve.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('ai-strategy', 'product', 4, 'AI strategy and portfolio', 'Choosing bets, build vs buy, and kill criteria.', 'Write a strategy with bets, kill criteria, and a review date.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('coe-design', 'product', 5, 'AI Center of Excellence design', 'Operating models that scale AI capability across an organization.', 'Stand up a CoE operating model with charter and metrics.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('verification', 'judgment', 1, 'Self-verification', 'Checking claims against real files, outputs, and tests before asserting.', 'Every claim in a handoff has a command or source behind it.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('calibration', 'judgment', 2, 'Calibration and uncertainty', 'Stating confidence that matches accuracy; abstaining when thin.', 'Show stated confidence tracks measured accuracy.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('scoping', 'judgment', 2, 'Scoping and success criteria', 'Turning vague asks into bounded, checkable goals.', 'Convert three vague requests into testable acceptance criteria.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('delegation', 'judgment', 3, 'Delegation briefs', 'Briefing a human or agent with goal, constraints, and done condition.', 'A delegate completes a task from the brief with no follow-up.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('human-agent-teaming', 'judgment', 4, 'Human-agent teaming', 'Dividing work between people and agents with clear approval gates.', 'Run a team workflow with measured throughput and zero gate bypasses.');
INSERT INTO skill (id, branch_id, tier, label, description, evidence) VALUES ('systems-thinking', 'judgment', 4, 'Systems thinking', 'Seeing feedback loops, second-order effects, and failure propagation.', 'Predict and prevent a second-order failure in a design review.');
