INSERT INTO role (id, label, bearer, description) VALUES ('ai-architect', 'AI Architect', 'human', 'Designs end-to-end AI systems: models, retrieval, tools, agents, safety, and cost.');
INSERT INTO role (id, label, bearer, description) VALUES ('ai-engineer', 'AI Engineer', 'human', 'Builds production LLM features and agents.');
INSERT INTO role (id, label, bearer, description) VALUES ('agent-engineer', 'Agent Engineer', 'human', 'Specializes in tool-using, long-running, and multi-agent systems.');
INSERT INTO role (id, label, bearer, description) VALUES ('ml-engineer', 'ML Engineer', 'human', 'Trains, fine-tunes, and serves models.');
INSERT INTO role (id, label, bearer, description) VALUES ('research-scientist', 'Applied Research Scientist', 'human', 'Advances model capability and understanding.');
INSERT INTO role (id, label, bearer, description) VALUES ('evals-engineer', 'Evals Engineer', 'human', 'Owns measurement: eval sets, judges, gates, and monitoring.');
INSERT INTO role (id, label, bearer, description) VALUES ('context-engineer', 'Prompt and Context Engineer', 'human', 'Designs instructions, examples, skills, and context pipelines.');
INSERT INTO role (id, label, bearer, description) VALUES ('mlops-engineer', 'AI Platform Engineer', 'human', 'Runs the AI platform: gateways, routing, observability, cost.');
INSERT INTO role (id, label, bearer, description) VALUES ('safety-lead', 'AI Safety and Governance Lead', 'human', 'Sets policy and controls for AI risk.');
INSERT INTO role (id, label, bearer, description) VALUES ('ai-pm', 'AI Product Manager', 'human', 'Decides what AI products ship and proves their value.');
INSERT INTO role (id, label, bearer, description) VALUES ('creative-director', 'AI Creative Director', 'human', 'Directs generated media with taste, consistency, and rights.');
INSERT INTO role (id, label, bearer, description) VALUES ('fde', 'Forward-Deployed AI Engineer', 'human', 'Ships AI into a customer''s systems and workflows.');
INSERT INTO role (id, label, bearer, description) VALUES ('caio', 'Chief AI Officer', 'human', 'Owns AI strategy, portfolio, governance, and capability across an organization.');
INSERT INTO role (id, label, bearer, description) VALUES ('ai-founder', 'AI-native Founder', 'human', 'Builds a company where agents do a large share of the work.');
INSERT INTO role (id, label, bearer, description) VALUES ('ai-fluent-professional', 'AI-fluent Professional', 'human', 'Any knowledge worker using AI daily with sound judgment.');
INSERT INTO role (id, label, bearer, description) VALUES ('coding-agent', 'Coding Agent', 'agent', 'Reads, writes, tests, and ships code changes.');
INSERT INTO role (id, label, bearer, description) VALUES ('research-agent', 'Research Agent', 'agent', 'Searches, reads, and synthesizes sourced answers.');
INSERT INTO role (id, label, bearer, description) VALUES ('orchestrator-agent', 'Orchestrator Agent', 'agent', 'Decomposes work, delegates to sub-agents, and synthesizes results.');
INSERT INTO role (id, label, bearer, description) VALUES ('memory-agent', 'Memory and Knowledge Agent', 'agent', 'Writes, consolidates, and retrieves durable knowledge.');
INSERT INTO role (id, label, bearer, description) VALUES ('judge-agent', 'Eval and Judge Agent', 'agent', 'Grades outputs and trajectories against rubrics.');
INSERT INTO role (id, label, bearer, description) VALUES ('security-agent', 'Security Reviewer Agent', 'agent', 'Reviews code, prompts, and configs for vulnerabilities.');
INSERT INTO role (id, label, bearer, description) VALUES ('creative-agent', 'Creative Production Agent', 'agent', 'Generates on-brief image, video, and audio assets.');
INSERT INTO role (id, label, bearer, description) VALUES ('analyst-agent', 'Data Analyst Agent', 'agent', 'Queries, analyzes, and visualizes data with sourced numbers.');
INSERT INTO role (id, label, bearer, description) VALUES ('ops-agent', 'Ops and SRE Agent', 'agent', 'Watches systems, triages incidents, and runs runbooks within gates.');
INSERT INTO role (id, label, bearer, description) VALUES ('support-agent', 'Customer Support Agent', 'agent', 'Answers customers from a knowledge base and escalates safely.');
INSERT INTO role (id, label, bearer, description) VALUES ('computer-use-agent', 'Computer-use Agent', 'agent', 'Operates browsers and desktop apps to finish GUI tasks.');
